 const references=await post('projects/references-list',{kind:'project',query:'HTTPS master',section:'all',offset:0}),reference=references.data.records[0],sharedSummary=await post('projects/references-tasks',{referenceReadToken:reference.referenceReadToken});assert.equal(sharedSummary.status,200);assert.equal(sharedSummary.data.matchCount,0);assert.equal(sharedSummary.data.manualStatus,'Active');assert.doesNotMatch(sharedSummary.body,/recordId|owner_id|description|taskToken|projectToken/);
 const listed=await post('projects/list',{}),root=listed.data.projects.find(p=>p.title==='Fictional HTTPS master');const structure=await post('projects/structure-list',{projectToken:root.projectToken,direction:'children',offset:0,query:''});assert.equal(structure.status,200);const review=await post('projects/structure-review',{projectToken:structure.data.projects[0].projectToken,linked:true});assert.equal(review.status,200);assert.equal((await post('projects/structure-save',{reviewId:review.data.reviewId,approved:true})).status,200);
 assert.equal((await post('search/project-read',{projectReadToken:search.data.results[0].projectReadToken})).status,409);assert.equal((await s.call('/auth/workspace/search/project-read',{method:'POST',headers:{'x-cc-csrf':'wrong'},body:{projectReadToken:'p'.repeat(43)}})).status,403);assert.equal((await post('projects/structure-cancel',{})).status,200);
