async function setup(t,options={}){const application=app(),router=createHttpsPrivateWorkspacePreview({origin,application,...options});t.after(()=>router.dispose());let cookie,csrf;
 async function call(path,{method='GET',headers={},body={},socket={encrypted:true,remoteAddress:'192.0.2.10'}}={}){const req={url:path,method,headers:{host:'workspace.example.test',...(cookie?{cookie}:{}),...(method==='POST'?{origin,'content-type':'application/json','x-cc-request':'workspace-session','x-cc-csrf':csrf}:{}),...headers},socket,async *[Symbol.asyncIterator](){yield JSON.stringify(body);}},res={writeHead(status,headers){this.status=status;this.headers=headers;return this;},end(body){this.body=body;}};await router.handle(req,res);let data;try{data=JSON.parse(res.body);}catch{}return{...res,data};}
 async function login(){const boot=await call('/auth/workspace/status');cookie=boot.headers['Set-Cookie'].split(';')[0];csrf=boot.data.csrf;const signed=await call('/auth/workspace/login',{method:'POST',body:{email:'demo@example.test',password:'fictional-only'}});assert.equal(signed.status,200);csrf=signed.data.csrf;return signed;}
 return{router,application,call,login};}
test('full HTTPS workspace serves only public allowlisted assets before login and never private source/config files',async t=>{const s=await setup(t);for(const path of ['/dev-dashboard.html','/dev-tasks.html','/dev-notes.html','/dev-calendar.html','/src/dev-private-brief.mjs']){const r=await s.call(path);assert.equal(r.status,200,path);assert.equal(r.headers['Cache-Control'],'no-store');assert.match(r.headers['Strict-Transport-Security'],/max-age/);}assert.equal((await s.call('/auth/workspace/brief')).status,401);for(const path of ['/.env.local','/server/private-workspace-sessions.mjs','/.local/provider-storage/encryption-key','/private-workspace-status.json','/auth/google/','/calendar-source-preview.html'])assert.equal((await s.call(path)).status,404,path);});
