test('a real certificate-verified HTTPS connection serves the workspace and protected records',async t=>{
 const {mkdtemp,readFile,rm}=await import('node:fs/promises'),{tmpdir}=await import('node:os'),{join}=await import('node:path'),{execFileSync}=await import('node:child_process'),https=await import('node:https'),dir=await mkdtemp(join(tmpdir(),'cc-workspace-tls-')),application=app(),router=createHttpsPrivateWorkspacePreview({origin,application});let server;
 t.after(async()=>{await router.dispose();if(server?.listening)await new Promise(done=>server.close(done));await rm(dir,{recursive:true,force:true});});
 execFileSync('/usr/bin/openssl',['req','-x509','-newkey','ec','-pkeyopt','ec_paramgen_curve:P-256','-nodes','-keyout',join(dir,'fictional-key.pem'),'-out',join(dir,'fictional-cert.pem'),'-days','1','-subj','/CN=workspace.example.test','-addext','subjectAltName=DNS:workspace.example.test'],{stdio:'ignore'});
 const key=await readFile(join(dir,'fictional-key.pem')),cert=await readFile(join(dir,'fictional-cert.pem'));server=https.createServer({key,cert},(req,res)=>void router.handle(req,res));await new Promise(done=>server.listen(0,'127.0.0.1',done));
 async function request(path,{method='GET',headers={},body}={}){return new Promise((done,reject)=>{const req=https.request({hostname:'127.0.0.1',port:server.address().port,servername:'workspace.example.test',ca:cert,rejectUnauthorized:true,path,method,headers:{host:'workspace.example.test',...headers},agent:false},res=>{let body='';res.on('data',chunk=>body+=chunk);res.on('end',()=>{let data;try{data=JSON.parse(body);}catch{}done({status:res.statusCode,headers:res.headers,body,data});});});req.on('error',reject);req.end(body?JSON.stringify(body):undefined);});}
 const boot=await request('/auth/workspace/status');assert.equal(boot.status,200);const cookie=boot.headers['set-cookie'][0].split(';')[0];assert.match(boot.headers['set-cookie'][0],/^__Host-cc_workspace=.*HttpOnly; SameSite=Strict; Path=\/; Max-Age=\d+; Secure$/);const headers={cookie,origin,'content-type':'application/json','x-cc-request':'workspace-session','x-cc-csrf':boot.data.csrf};const signed=await request('/auth/workspace/login',{method:'POST',headers,body:{email:'demo@example.test',password:'fictional-only'}});assert.equal(signed.status,200);headers['x-cc-csrf']=signed.data.csrf;
 assert.equal((await request('/dev-dashboard.html')).status,200);assert.equal((await request('/auth/workspace/brief',{headers:{cookie}})).status,200);const emptyBrowser=await request('/auth/workspace/brief');assert.equal(emptyBrowser.status,401);assert.equal((await request('/auth/workspace/logout',{method:'POST',headers})).status,200);assert.equal((await request('/auth/workspace/brief',{headers:{cookie}})).status,401);
});
