test('HTTPS academic identity adoption reuses one-use approval and leaves academic content unchanged',async t=>{const s=await setup(t);await s.login();const post=(path,body)=>s.call('/auth/workspace/'+path,{method:'POST',body}),overview=await post('school/overview',{}),course=overview.data.courses.find(c=>c.code==='D253'),before=await post('school/read',{schoolReadToken:course.schoolReadToken}),edit=await post('school/edit-read',{schoolReadToken:course.schoolReadToken}),review=await post('school/identity-review',{editToken:edit.data.editToken});assert.equal(review.status,200);assert.deepEqual(review.data.identityAssignment,{assessments:1,steps:1,studySessions:1});assert.doesNotMatch(review.body,/academicId|payload|owner_id/);assert.equal((await post('school/edit-save',{reviewId:review.data.reviewId,approved:true})).status,200);const latest=await post('school/overview',{}),selected=latest.data.courses.find(c=>c.code==='D253'),after=await post('school/read',{schoolReadToken:selected.schoolReadToken});assert.deepEqual({...after.data,expiresAt:0},{...before.data,expiresAt:0});const again=await post('school/edit-read',{schoolReadToken:selected.schoolReadToken});assert.deepEqual((await post('school/identity-review',{editToken:again.data.editToken})).data,{noChanges:true});});

test('HTTPS existing assessments and steps save through canonical reviewed academic outlines',async t=>{const s=await setup(t);await s.login();const post=(path,body)=>s.call('/auth/workspace/'+path,{method:'POST',body}),open=async()=>{const overview=await post('school/overview',{}),row=overview.data.courses.find(c=>c.code==='D253');return{row,edit:(await post('school/edit-read',{schoolReadToken:row.schoolReadToken})).data};};let selected=await open();assert.equal((await post('school/academic-read',{editToken:selected.edit.editToken})).status,409);const identity=await post('school/identity-review',{editToken:selected.edit.editToken});assert.equal((await post('school/edit-save',{reviewId:identity.data.reviewId,approved:true})).status,200);selected=await open();const outline=await post('school/academic-read',{editToken:selected.edit.editToken});assert.equal(outline.status,200);const a=outline.data.assessments[0];a.title='Reviewed fictional assessment <literal>';a.status='Submitted';a.tasks[0].title='Reviewed fictional step';a.tasks[0].done=true;const review=await post('school/academic-review',{editToken:selected.edit.editToken,viewId:outline.data.viewId,assessments:outline.data.assessments});assert.equal(review.status,200);assert.equal(review.data.academicChanges.length,4);assert.equal((await post('school/edit-save',{reviewId:review.data.reviewId,approved:true})).status,200);selected=await open();const details=await post('school/read',{schoolReadToken:selected.row.schoolReadToken});assert.equal(details.data.assessments[0].title,a.title);assert.equal(details.data.assessments[0].tasks[0].done,true);assert.equal(details.data.notes,'Exact fictional course notes\n<literal> detail.');assert.equal(details.data.officialOrder,4);assert.equal(details.data.studyOrder,1);assert.equal(details.data.studySessions[0].title,'Fictional study block');});

