 const {createPrivateSchoolPanel}=await import('../src/private-school-panel.mjs');const s=await setup(t);await s.login();const post=async(path,body)=>{const result=await s.call('/auth/workspace/'+path,{method:'POST',body});if(result.status!==200)throw Error('Fictional HTTP action refused');return result.data;},overview=await post('school/overview',{}),token=overview.courses.find(c=>c.code==='D253').schoolReadToken,opened=await post('school/edit-read',{schoolReadToken:token}),review=await post('school/edit-review',{editToken:opened.editToken,fields:{...opened.fields,notes:'Newer current metadata before historical correction'}});await post('school/edit-save',{reviewId:review.reviewId,approved:true});
 const client={schoolOverview:()=>post('school/overview',{}),schoolRead:v=>post('school/read',v),schoolHistoryList:v=>post('school/history-list',v),schoolHistoryRead:v=>post('school/history-read',v),schoolEditRead:t=>post('school/edit-read',{schoolReadToken:t}),schoolEditReview:v=>post('school/edit-review',v),schoolEditSave:reviewId=>post('school/edit-save',{reviewId,approved:true}),schoolEditCancel:()=>post('school/edit-cancel',{})},panel=createPrivateSchoolPanel({client,canUse:()=>true,allowHistory:true,allowEdit:true});t.after(()=>panel.dispose());const turn=()=>new Promise(resolve=>setImmediate(resolve)),click=selector=>panel.click({target:{closest:s=>s===selector?{}:null}}),openCourse=async()=>{const source=panel.render().match(/data-school-read="([^"]+)"[^>]*>Open School record: Fictional Values-Based Leadership/)[1];panel.click({target:{closest:s=>s==='[data-school-read]'?{dataset:{schoolRead:source}}:null}});await turn();return source;};click('#private-school-open');await turn();const source=await openCourse();click('#private-school-history-open');await turn();const old=panel.render().match(/data-school-history-read="([^"]+)"/)[1];panel.click({target:{closest:s=>s==='[data-school-history-read]'?{dataset:{schoolHistoryRead:old}}:null}});await turn();click('#private-school-history-use');await turn();assert.match(panel.render(),/Draft uses metadata from saved version 1/);assert.match(panel.render(),/Exact fictional course notes/);assert.equal((await post('school/read',{schoolReadToken:source})).notes,'Newer current metadata before historical correction');panel.submit({target:{id:'private-school-edit-form'},preventDefault(){}});await turn();assert.match(panel.render(),/Before/);assert.match(panel.render(),/Newer current metadata before historical correction/);assert.equal((await post('school/read',{schoolReadToken:source})).notes,'Newer current metadata before historical correction');click('#private-school-edit-approve');await turn();const latest=await openCourse();assert.equal((await post('school/read',{schoolReadToken:latest})).notes,'Exact fictional course notes\n<literal> detail.');const history=await post('school/history-list',{schoolReadToken:latest});assert.equal(history.matchCount,2);assert.equal((await post('school/read',{schoolReadToken:latest})).officialOrder,4);
